def button(text='Request a quote',href='/request-a-quote/',secondary=False):
 return f'<a class="button {"secondary" if secondary else ""}" href="{href}">{text}</a>'
def eyebrow(t):return ''
def cta():return f'<section class="closing wrap"><div><h2>Let’s find your<br>next great deal.</h2><p>Tell us what you have in mind. We’ll take it from there.</p></div>{button()}</section>'
def intro(kicker,title,desc):return f'<section class="page-intro wrap">{eyebrow(kicker)}<h1>{title}</h1><p class="lead">{desc}</p></section>'
def layout(path,title,desc,body,draft=False):
 links=''.join(f'<a href="{url}" {"aria-current=page" if url==path else ""}>{label}</a>' for url,label in nav if url != "/")
 story_assets = '<link rel="stylesheet" href="/assets/customer-stories.css"><script src="/assets/customer-stories.js" defer></script>' if path == '/' else ('<link rel="stylesheet" href="/assets/customer-stories.css">' if path in ('/customer-stories/california/', '/customer-stories/virginia/', '/customer-stories/liz/', '/customer-stories/joanne/') else '')
 if path == '/customer-stories/':
  story_assets = '<link rel="stylesheet" href="/assets/story-index.css">'
 if path in ('/customer-stories/', '/services/', '/about/', '/contact/'):
  story_assets += '<link rel="stylesheet" href="/assets/road-hero.css"><script src="/assets/road-hero.js" defer></script>'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Done Deal Auto Group</title><meta name="description" content="{html.escape(desc,quote=True)}">{('<meta name="robots" content="noindex,nofollow">' if draft else '')}<meta name="theme-color" content="#155bff"><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='7' fill='%23155bff'/%3E%3Ctext x='7' y='25' font-family='Arial' font-weight='900' font-size='25' fill='white'%3ED%3C/text%3E%3C/svg%3E"><link rel="stylesheet" href="/assets/scrollcraft-engine.css"><link rel="stylesheet" href="/assets/styles.css"><link rel="stylesheet" href="/assets/enterprise.css">{('<link rel="stylesheet" href="/assets/campaign.css">' if path=='/' else '')}{story_assets}<link rel="stylesheet" href="/assets/site-chrome.css"><script src="/assets/scrollcraft-engine.js" defer></script><script src="/assets/site.js" defer></script><script src="/assets/enterprise.js" defer></script></head><body class="{'home-page' if path=='/' else 'interior-page'}"><a class="skip" href="#main">Skip to content</a><header><div class="nav-wrap wrap"><a class="brand" href="/" aria-label="Done Deal Auto Group home"><span class="site-brand-mark" aria-hidden="true"><img src="/assets/logo.png" width="574" height="490" alt=""></span><span class="brand-name">DONE DEAL<small>AUTO GROUP</small></span></a><nav id="navigation" aria-label="Main navigation">{links}</nav>{button('Request a quote')}<button class="menu-toggle" type="button" aria-expanded="false" aria-label="Open menu" aria-controls="navigation"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true" focusable="false"><path class="site-menu-bars" d="M4 6h16M4 12h13M4 18h10"/><path class="site-menu-close" d="m6 6 12 12M18 6 6 18"/></svg></button></div></header><main id="main">{body}</main>{render_footer(nav)}</body></html>'''
